components-form-select--select-default.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlSelectComponent } from '@domg-wc/components/form';

registerWebComponents([VlSelectComponent]);

const options = [
    { label: 'Hasselt', value: 'hasselt' },
    { label: 'Turnhout', value: 'turnhout' },
    { label: 'Knokke-Heist', value: 'knokke-heist' },
    { label: 'Waregem', value: 'waregem' },
    { label: 'Lier', value: 'lier' },
    { label: 'Rio Piedras', value: 'rio piedras' },
];
const select = document.querySelector('#geboorteplaats');
// Geef een nieuwe array mee om de opties te wijzigen: vl-select bouwt zich enkel opnieuw op bij een nieuwe referentie.
select.options = options;
// vl-select neemt initialOptions over wanneer het element op de pagina komt, en zet bij een reset van de form options
// terug op initialOptions. Zet je options pas daarna, zoals hier, zet dan ook initialOptions; anders is de lijst leeg
// na een reset.
select.initialOptions = options;

// event.detail.value is de value van de gekozen optie, of '' zonder keuze.
select.addEventListener('vl-change', (event) => {
    console.log(event.detail.value);
});

